using System.Text.Json;
using Arcoll.WinUI3.Services;
int checks=0;void Check(bool ok,string why){checks++;if(!ok)throw new Exception(why);}
var internet=new PageDataLoad("Clique para iniciar o teste");Check(internet.Current.Phase==DataLoadPhase.Waiting&&!internet.Current.HasData,"Internet starts waiting for explicit collection");var notifications=0;internet.Changed+=()=>notifications++;var first=internet.Begin("Medindo a conexão");Check(internet.Current.Phase==DataLoadPhase.Loading&&!internet.Current.HasData,"opening or starting never implies data exists");internet.Report("Recebendo dados",30,first);Check(internet.Current.Percent==30&&!internet.Current.HasData,"actual progress retained until result");internet.Report("Organizando os resultados",100,first);Check(internet.Current.Percent==99&&!internet.Current.HasData,"100 is reserved for actual completion");internet.Fail("Falha de conexão",first);Check(internet.Current.Phase==DataLoadPhase.Failed&&!internet.Current.HasData,"network failure retains retry gate");internet.Report("Late progress",99,first);Check(internet.Current.Phase==DataLoadPhase.Failed,"late progress cannot resurrect failed request");var retry=internet.Begin("Nova tentativa");internet.Complete("Old result",first);Check(!internet.Current.HasData&&internet.Current.Operation==retry,"stale result cannot finish newer operation");internet.Complete("Dados disponíveis",retry);Check(internet.Current.Phase==DataLoadPhase.Ready&&internet.Current.Percent==100&&internet.Current.HasData,"real completion reveals content");internet.Report("Late progress",75,retry);Check(internet.Current.Phase==DataLoadPhase.Ready,"late progress never overwrites a finished result");Check(notifications>=7,"state changes notify UI");
var list=new PageDataLoad("Consultando inventário",true);Check(list.Current.Phase==DataLoadPhase.Loading&&!list.Current.HasData,"automatic reads begin behind gate");list.Begin("Lendo listagem");list.Complete("Nenhum chamado encontrado");Check(list.Current.HasData,"successful empty query is usable data");list.Begin("Atualização em segundo plano",preserveData:true);list.Fail("Offline");Check(list.Current.HasData,"failed background refresh retains valid existing data");list.Begin("Nova coleta explícita");Check(!list.Current.HasData,"explicit recollection may hide old content");list.Wait("Escolha as opções");Check(list.Current.Phase==DataLoadPhase.Waiting&&!list.Current.HasData,"input-required page does not fake a result");
using var catalog=JsonDocument.Parse(File.ReadAllText("assets/themes/catalog.json"));foreach(var theme in catalog.RootElement.GetProperty("themes").EnumerateObject())foreach(var variant in new[]{"light","dark"}){var v=theme.Value.GetProperty("variants").GetProperty(variant);var c=LoadingColors.Create(v.GetProperty("surface").GetString()!,v.GetProperty("text").GetString()!,v.GetProperty("muted").GetString()!,v.GetProperty("accent").GetString()!);Check(c.Surface==v.GetProperty("surface").GetString(),"published background respected");Check(LoadingColors.Contrast(c.Text,c.Surface)>=4.5,"readable loading text: "+theme.Name+variant);Check(LoadingColors.Contrast(c.Muted,c.Surface)>=4.5,"readable loading hints");Check(LoadingColors.Contrast(c.Accent,c.Surface)>=3,"visible ring and animation");Check(c.Track!=c.Accent&&c.Track!=c.Text,"track, ring and foreground never flatten to one color");}
foreach(var color in new[]{"#ffffff","#000000","#777777","#1b293e"}){var c=LoadingColors.Create(color,color,color,color);Check(LoadingColors.Contrast(c.Text,c.Surface)>=4.5&&LoadingColors.Contrast(c.Accent,c.Surface)>=3,"monochrome published palette stays readable");}
Console.WriteLine($"PASS {checks} loading lifecycle, explicit collection, retries and theme contrast assertions.");
